/*
 * A071765  Number of n-tuples of elements e_1,e_2,...,e_n in the alternating
 *          group A_4 such that the subgroup generated by e_1,e_2,...,e_n is
 *          A_4.
 * https://oeis.org/A071765
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = (3^n-1) * (4^n-4) (offset 1)
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 8, u64 n <= 17, u128 n <= 35,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Fast exponentiation by repeated multiplication.
       For n up to about 10000 this simple loop is well within time limits.  */
    seq_t pow3 = (seq_t)1;
    seq_t pow4 = (seq_t)1;

    for (idx_t i = 0; i < n; ++i) {
        pow3 *= (seq_t)3;
        pow4 *= (seq_t)4;
    }

    /* Compute the formula.  All intermediate results fit in seq_t
       as guaranteed by the problem statement. */
    seq_t first  = pow3 - (seq_t)1;
    seq_t second = pow4 - (seq_t)4;

    return first * second;
}
